var STORY = [{"n":1,"title":"Opening, meet Jeff","splash":false,"layout":"wide strip on top, a tall panel and a small panel side by side in the middle, a large panel at the bottom.","note":"","panels":[{"n":1,"size":"Wide, Top Third","desc":"Dawn over Durian City, a state of the art city like Makati. Glass towers catching the golden sunrise, wide avenues, colorful jeepneys driving along them, a few palm and durian trees along the street.","lines":[{"k":"cap","who":"","mod":"","t":"\"Durian City, Mindanao. 6:42 AM.\""},{"k":"sfx","who":"","mod":"giongo","t":"VROOOM, HONK HONK"},{"k":"sfx","who":"","mod":"gitaigo","t":"KINANG (the towers shining in the sunrise)"}],"rect":[3.0,3.0,94.0,19.98]},{"n":2,"size":"Tall, Middle Left","desc":"The gate of Durian City High School. Flag, painted sign, students trickling in, the modern skyline behind the school.","lines":[{"k":"sfx","who":"","mod":"giseigo","t":"DALDAL DALDAL (the chatter of the crowd)"},{"k":"sfx","who":"","mod":"giseigo","t":"BULONG BULONG (students whisper as Jeff walks by: \"That's the folklore guy.\")"},{"k":"sfx","who":"","mod":"giongo","t":"KRIIIK (the gate swinging)"}],"rect":[3.0,24.58,49.96,27.24]},{"n":3,"size":"Small, Middle Right","desc":"Close up: a necklace swinging against a blue uniform shirt. One tiny glint. No explanation.","lines":[{"k":"sfx","who":"","mod":"gitaigo","t":"KISLAP, TIBOK (a tiny glint and a tiny heartbeat, like the necklace is alive)"}],"rect":[55.36,24.58,41.64,27.24]},{"n":4,"size":"Large Low Angle, Bottom Half","desc":"Jeff walks toward the camera. Ube colored hair in the wind, one hand in his pocket, the other holding a thick book on Philippine folklore. Tall, lean, effortless.","lines":[{"k":"sfx","who":"","mod":"giongo","t":"SWISH (hair in the wind), TAP TAP (footsteps)"},{"k":"sfx","who":"","mod":"gitaigo","t":"KINTAB (a cool glow around Jeff)"},{"k":"cap","who":"","mod":"","t":"\"Jefferson Victorio. He looks like the cool one.\""},{"k":"cap","who":"","mod":"","t":"\"His classmates call him weird. He reads about ancient spirits for breakfast.\""}],"rect":[3.0,53.42,94.0,43.58]}]},{"n":2,"title":"Meet Hal","splash":false,"layout":"wide strip on top, two small panels, then a tall panel on the left and a large panel on the right.","note":"","panels":[{"n":1,"size":"Wide, Top","desc":"Behind Jeff, a tiny figure sprints through the crowd, a backpack bigger than he is.","lines":[{"k":"sfx","who":"","mod":"","t":"TAP TAP TAP TAP"}],"rect":[3.0,3.0,94.0,22.7]},{"n":2,"size":"Small","desc":"Jeff does not turn around. Small smirk.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"Three. Two. One.\""}],"rect":[3.0,27.3,45.8,18.16]},{"n":3,"size":"Small","desc":"Hal crashes into Jeff's back. Glasses slide down his nose.","lines":[{"k":"sfx","who":"","mod":"","t":"THUD"},{"k":"say","who":"Hal","mod":"","t":"\"JEFF! Wait up!\""}],"rect":[51.2,27.3,45.8,18.16]},{"n":4,"size":"Tall, Left","desc":"Hal's face close up. Brown hair, round glasses, big eyes. He is very cute and very offended.","lines":[{"k":"say","who":"Hal","mod":"","t":"\"You walked past the bakery again! I texted you six times!\""}],"rect":[3.0,47.06,36.64,49.94]},{"n":5,"size":"Large, Right","desc":"The height gap. Jeff looks down, Hal looks up, a paper bag of pandesal held high like a trophy.","lines":[{"k":"say","who":"Hal","mod":"","t":"\"I got your favorite.\""},{"k":"say","who":"Jeff","mod":"","t":"\"You're a legend.\""},{"k":"cap","who":"","mod":"","t":"\"Hal Bautista. Loudest voice in any room.\""}],"rect":[42.04,47.06,54.96,49.94]}]},{"n":3,"title":"Meet Mel","splash":false,"layout":"wide strip on top, a tall panel on the left, three stacked small panels in the middle, a large panel at the bottom.","note":"","panels":[{"n":1,"size":"Wide, Top","desc":"Violin music drifts across the school grounds. Students stop on the stairs. Glowing musical notes weave through the air.","lines":[],"rect":[3.0,3.0,94.0,14.53]},{"n":2,"size":"Tall, Left","desc":"Mel on the school steps, eyes closed, long blonde hair over his shoulder, violin tucked under his chin. A very big, very gentle guy.","lines":[],"rect":[3.0,19.13,41.22,39.95]},{"n":3,"size":"Small","desc":"Jeff and Hal arrive at the bottom of the steps. Hal waves with the pandesal bag.","lines":[],"rect":[46.62,19.13,50.38,12.25]},{"n":4,"size":"Small","desc":"Mel opens his eyes and smiles without stopping the music.","lines":[],"rect":[46.62,32.98,50.38,12.25]},{"n":5,"size":"Small","desc":"Mel's bow slows, then stops.","lines":[{"k":"say","who":"Mel","mod":"","t":"\"Good morning. I made something new.\""}],"rect":[46.62,46.83,50.38,12.25]},{"n":6,"size":"Large, Bottom","desc":"The trio together. Hal has climbed two steps to reach Mel's shoulder height. Jeff leans on the railing with his book.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"It sounds like sunrise.\""},{"k":"say","who":"Hal","mod":"","t":"\"It sounds like pandesal.\""},{"k":"say","who":"Mel","mod":"","t":"\"Both are correct.\""},{"k":"cap","who":"","mod":"","t":"\"Mel Charlie Abaldado. The violin is the one thing that always makes sense to him.\""}],"rect":[3.0,60.68,94.0,36.32]}]},{"n":4,"title":"Meet Nikki","splash":false,"layout":"wide strip on top, a small panel and a tall panel, a large low angle panel in the middle, a medium panel at the bottom.","note":"","panels":[{"n":1,"size":"Wide, Top","desc":"The gate opens. Wind. A group of girls in white blouses and skirts. No dialogue.","lines":[],"rect":[3.0,3.0,94.0,17.84]},{"n":2,"size":"Small","desc":"Hal freezes mid bite.","lines":[{"k":"say","who":"Hal","mod":"","t":"\"...No.\""}],"rect":[3.0,22.44,45.8,23.19]},{"n":3,"size":"Tall","desc":"Students step aside, one after another, like a slow wave.","lines":[],"rect":[51.2,22.44,45.8,23.19]},{"n":4,"size":"Large Low Angle","desc":"Nikki walks forward, hair in the wind, her friends flanking her. She owns the sidewalk.","lines":[{"k":"cap","who":"","mod":"","t":"\"Nikki Sharon Legazpi. The most popular girl in school.\""}],"rect":[3.0,47.23,94.0,26.76]},{"n":5,"size":"Medium, Bottom","desc":"She stops in front of the trio. Smug.","lines":[{"k":"say","who":"Nikki","mod":"","t":"\"Look. The nerd, the giant, and the pocket edition.\""}],"rect":[3.0,75.59,94.0,21.41]}]},{"n":5,"title":"Nikki picks on Hal","splash":false,"layout":"small panel, wide panel, three small panels in a row, and a medium panel at the bottom.","note":"","panels":[{"n":1,"size":"Small","desc":"Hal bristles, finger raised.","lines":[{"k":"say","who":"Hal","mod":"","t":"\"I am NOT a pocket edition!\""}],"rect":[3.0,3.0,27.48,19.98]},{"n":2,"size":"Wide","desc":"Nikki plucks his glasses off his face and holds them high. Her friends laugh.","lines":[],"rect":[32.88,3.0,64.12,19.98]},{"n":3,"size":"Small","desc":"Hal's blurry point of view: smears of color and shapes.","lines":[{"k":"say","who":"Hal","mod":"thought bubble","t":"\"I can't see anything\""}],"rect":[3.0,24.58,29.73,21.79]},{"n":4,"size":"Small","desc":"Hal jumping, fingertips short of the glasses.","lines":[{"k":"say","who":"Nikki","mod":"","t":"\"Aww. He can't even jump.\""}],"rect":[35.13,24.58,29.73,21.79]},{"n":5,"size":"Small","desc":"Mel lowers the violin, troubled.","lines":[{"k":"say","who":"Mel","mod":"","t":"\"Nikki, please. Those are his.\""}],"rect":[67.27,24.58,29.73,21.79]},{"n":6,"size":"Medium, Bottom","desc":"Jeff calm. His necklace swings once against his chest.","lines":[],"rect":[3.0,47.97,94.0,49.03]}]},{"n":6,"title":"Jeff steps in","splash":false,"layout":"wide panel, two medium panels, a small panel, and a large panel at the bottom that ends on a cliffhanger.","note":"","panels":[{"n":1,"size":"Wide","desc":"Jeff steps between Nikki and Hal. We see his back. Hal peeks out behind his arm.","lines":[],"rect":[3.0,3.0,94.0,16.06]},{"n":2,"size":"Medium","desc":"Jeff, steady.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"Give them back.\""},{"k":"say","who":"Nikki","mod":"","t":"\"Make me.\""}],"rect":[3.0,20.66,45.8,19.62]},{"n":3,"size":"Medium","desc":"Jeff's smirk.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"Do you ever get tired of being this predictable?\""},{"k":"say","who":"Nikki","mod":"","t":"\"Do you ever get tired of reading about ghosts?\""}],"rect":[51.2,20.66,45.8,19.62]},{"n":4,"size":"Small","desc":"Hal, from behind Jeff.","lines":[{"k":"say","who":"Hal","mod":"","t":"\"They're not ghosts. It's folklore!\""},{"k":"say","who":"Mel","mod":"off panel","t":"\"It's technically mythology.\""}],"rect":[3.0,41.88,94.0,12.49]},{"n":5,"size":"Large","desc":"Nikki, smug and annoyed, flings Hal's glasses high over Jeff's head in a big arc, her arm swung out in a showy throw, with speed lines and a glint on the lenses. Her friends gasp.","lines":[{"k":"say","who":"Nikki","mod":"","t":"\"Fine. Go fetch.\""},{"k":"sfx","who":"","mod":"","t":"FLING"}],"rect":[3.0,55.97,94.0,41.03]}]},{"n":7,"title":"Jeff proves the point","splash":true,"layout":"one full page image.","note":"this is the page that shows Jeff is more than the weird folklore kid. Everyone else in the frame is in comic shock, Jeff is the only calm face. He looks cool, and for one moment the school sees it. Nikki's girls fall for him on the spot.","panels":[{"n":1,"size":"Full Page","desc":"Jeff, without even turning around, reaches up and catches the glasses between two fingers, calm and stylish. Dramatic angle from slightly below. Behind him Hal's eyes are huge, Mel's bow is frozen mid air, the students are frozen. Nikki's friends have their hands over their mouths and small hearts in their eyes. Leaves and dust float in a shaft of morning sun. Nikki's face is shocked.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"Careful. Those are his.\""},{"k":"cap","who":"","mod":"tiny, bottom corner","t":"\"Jeff Victorio never starts a fight. He just never lets his friends stand alone.\""}],"rect":[3.0,3.0,94.0,94.0]}]},{"n":8,"title":"Aftermath","splash":false,"layout":"wide panel, two small panels, a medium panel, a small panel, and a wide panel at the bottom.","note":"","panels":[{"n":1,"size":"Wide","desc":"Silence. Then a long dreamy sigh from Nikki's friends, with tiny hearts floating up. The school bell rings.","lines":[{"k":"sfx","who":"","mod":"","t":"KRIIIIING"}],"rect":[3.0,3.0,94.0,18.3]},{"n":2,"size":"Small","desc":"Nikki's friends crowd around Jeff, starry eyed.","lines":[{"k":"say","who":"Nikki'S Friend","mod":"","t":"\"He caught it without even looking.\""},{"k":"say","who":"Nikki'S Other Friend","mod":"","t":"\"Okay, who knew?\""}],"rect":[3.0,22.9,45.8,20.58]},{"n":3,"size":"Small","desc":"Nikki, jaw tight, a stiff smile, snatches up her bag.","lines":[{"k":"say","who":"Nikki","mod":"","t":"\"Nice catch, Jeff. Finally, a use for all that ghost reading.\""}],"rect":[51.2,22.9,45.8,20.58]},{"n":4,"size":"Medium","desc":"Jeff gently puts the glasses back on Hal and straightens them.","lines":[{"k":"say","who":"Hal","mod":"","t":"\"Thanks, Jeff.\""},{"k":"say","who":"Jeff","mod":"","t":"\"Don't mention it. Actually, mention it. I want credit.\""}],"rect":[3.0,45.08,55.76,27.45]},{"n":5,"size":"Small","desc":"Hal laughs through wet eyes.","lines":[],"rect":[61.16,45.08,35.84,27.45]},{"n":6,"size":"Wide, Bottom","desc":"The three walk toward the school, Mel playing softly. Far behind them, Nikki drags her friends along, and the friends keep looking back at Jeff. Nikki glances back for half a second.","lines":[{"k":"say","who":"Nikki","mod":"","t":"\"Whatever. Come on, girls.\""},{"k":"say","who":"Nikki'S Friend","mod":"","t":"\"Nik?\""},{"k":"say","who":"Nikki","mod":"","t":"\"Nothing.\""}],"rect":[3.0,74.13,94.0,22.87]}]},{"n":9,"title":"Homeroom, meet Sir Archie","splash":false,"layout":"wide panel on top, small panel, medium panel, small panel, large panel at the bottom.","note":"","panels":[{"n":1,"size":"Wide","desc":"Homeroom. Ceiling fans, chalk dust, open windows with a view of the courtyard.","lines":[],"rect":[3.0,3.0,94.0,16.34]},{"n":2,"size":"Small","desc":"Sir Archie at the front. Cool, tall, muscular young teacher with white hair and rectangle glasses, tight buttoned shirt and a cardigan, a coffee thermos on the desk.","lines":[{"k":"cap","who":"","mod":"","t":"\"Mr. Archibald Oronies. Everyone calls him Sir Archie.\""}],"rect":[3.0,20.94,23.79,21.79]},{"n":3,"size":"Medium","desc":"Roll call, quick cuts of each of the four.","lines":[{"k":"say","who":"Sir Archie","mod":"","t":"\"Victorio?\""},{"k":"say","who":"Jeff","mod":"","t":"\"Present, sir.\""},{"k":"say","who":"Sir Archie","mod":"","t":"\"Bautista?\""},{"k":"say","who":"Hal","mod":"","t":"\"Here, Sir! Alive!\""},{"k":"say","who":"Sir Archie","mod":"","t":"\"Abaldado?\" MEL: \"Present.\""},{"k":"say","who":"Sir Archie","mod":"","t":"\"Legazpi?\" NIKKI: \"...Present.\""}],"rect":[29.19,20.94,41.63,21.79]},{"n":4,"size":"Small","desc":"Seats: the three in a row, Nikki one row ahead. She turns to glare at them.","lines":[],"rect":[73.21,20.94,23.79,21.79]},{"n":5,"size":"Large","desc":"Sir Archie writes on the board in big letters: SANGKAPULUAN.","lines":[],"rect":[3.0,44.34,94.0,52.66]}]},{"n":10,"title":"The lesson","splash":false,"layout":"medium panel, wide illustrated panel, small panel, medium panel, small panel, small panel.","note":"","panels":[{"n":1,"size":"Medium","desc":"Sir Archie.","lines":[{"k":"say","who":"Sir Archie","mod":"","t":"\"Before we start, a story. Long ago, our ancestors called these islands the Sangkapuluan.\""}],"rect":[3.0,3.0,36.64,31.13]},{"n":2,"size":"Wide","desc":"The islands drawn like an ancient map. Ten small points glow along the map.","lines":[{"k":"cap","who":"","mod":"","t":"\"Ten.\""}],"rect":[42.04,3.0,54.96,31.13]},{"n":3,"size":"Small","desc":"Hal whispers.","lines":[{"k":"say","who":"Hal","mod":"","t":"\"Ten what?\""},{"k":"say","who":"Jeff","mod":"whispering back, eyes sparkling","t":"\"Agimats.\""}],"rect":[3.0,35.73,36.64,28.54]},{"n":4,"size":"Medium","desc":"Sir Archie.","lines":[{"k":"say","who":"Sir Archie","mod":"","t":"\"Every land has its Agimats. Charms with a power of their own. Ten are said to sleep in the Sangkapuluan, our islands.\""}],"rect":[42.04,35.73,54.96,28.54]},{"n":5,"size":"Small","desc":"Nikki, bored.","lines":[{"k":"say","who":"Nikki","mod":"","t":"\"So it's a fairy tale, Sir?\" The class laughs."},{"k":"say","who":"Sir Archie","mod":"","t":"\"Every fairy tale begins with someone who stopped listening.\""}],"rect":[3.0,65.87,45.8,31.13]},{"n":6,"size":"Small","desc":"Jeff's hand drifts to his collar and closes around the necklace.","lines":[],"rect":[51.2,65.87,45.8,31.13]}]},{"n":11,"title":"After school","splash":false,"layout":"wide panel, two small panels, a medium panel, a large panel at the bottom.","note":"","panels":[{"n":1,"size":"Wide","desc":"The school gate in the golden afternoon light. The bell has rung. Students stream out. The three friends split at the gate.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"I have to get home early. Mama needs me.\""},{"k":"say","who":"Mel","mod":"","t":"\"Violin lesson. See you tomorrow.\""},{"k":"say","who":"Hal","mod":"","t":"\"Science club. I'm building a robot. It's going to be taller than me.\""}],"rect":[3.0,3.0,94.0,19.62]},{"n":2,"size":"Small","desc":"The three wave and head off in different directions.","lines":[{"k":"sfx","who":"","mod":"","t":"\"TAP TAP\""}],"rect":[3.0,24.22,45.8,16.06]},{"n":3,"size":"Small","desc":"Far down the school wall, a tall, slender boy leans alone with his hands in his pockets and earbuds in. Nobody looks at him.","lines":[],"rect":[51.2,24.22,45.8,16.06]},{"n":4,"size":"Medium","desc":"Close up on him. Long dark emo hair over one eye, a small nose piercing, tattoos down his right arm, a spiked belt and stacks of bracelets. He wears the same blue school shirt and khaki pants as everyone else, but worn the punk way.","lines":[{"k":"cap","who":"","mod":"","t":"\"Jared Callao. Spikes outside, quiet inside.\""}],"rect":[3.0,41.88,94.0,12.49]},{"n":5,"size":"Large","desc":"A huge shadow falls over Jared. He pulls out one earbud and looks up. Dan Macabebe stands in front of him, blocking the whole path.","lines":[{"k":"cap","who":"","mod":"","t":"\"Dan Macabebe. Big. Loud. Allergic to being told no.\""},{"k":"say","who":"Dan","mod":"","t":"\"Well, well. Still wearing your costume, freak?\""}],"rect":[3.0,55.97,94.0,41.03]}]},{"n":12,"title":"The bully","splash":false,"layout":"a large panel and a tall panel, two small panels, a wide panel at the bottom.","note":"show the shoving and the cruelty, but nothing graphic. Jared only gets slight bruises. The point is that he is alone and nobody helps.","panels":[{"n":1,"size":"Large","desc":"Dan shoves Jared back against the wall with one hand on his chest.","lines":[{"k":"say","who":"Dan","mod":"","t":"\"Nice hair. Nice nose ring. Who are you trying to scare?\""},{"k":"say","who":"Jared","mod":"","t":"\"Get off me.\""}],"rect":[3.0,3.0,59.54,36.32]},{"n":2,"size":"Tall","desc":"Jared's face close up. Cold, calm eyes behind the hair. His jaw is set. He does not fight back.","lines":[],"rect":[64.94,3.0,32.06,36.32]},{"n":3,"size":"Small","desc":"Jared tries to walk away. Dan grabs his bag strap and yanks him back.","lines":[{"k":"sfx","who":"","mod":"","t":"\"YANK\""}],"rect":[3.0,40.92,45.8,18.16]},{"n":4,"size":"Small","desc":"Dan shoves Jared down. Jared catches himself on his arm and scrapes it on the ground.","lines":[{"k":"sfx","who":"","mod":"","t":"\"THUD\""}],"rect":[51.2,40.92,45.8,18.16]},{"n":5,"size":"Wide","desc":"Wide shot of the path. Dan towering over Jared on the ground. A few students walk past in the background, look the other way, and keep walking. No one stops.","lines":[],"rect":[3.0,60.68,94.0,36.32]}]},{"n":13,"title":"No one helps","splash":false,"layout":"two small panels, a wide panel, a large panel at the bottom.","note":"","panels":[{"n":1,"size":"Small","desc":"Dan rips one of Jared's bracelets off his wrist.","lines":[{"k":"sfx","who":"","mod":"","t":"\"SNAP\""}],"rect":[3.0,3.0,45.8,16.34]},{"n":2,"size":"Small","desc":"Jared on the ground, still. He does not cry out. He just stares.","lines":[],"rect":[51.2,3.0,45.8,16.34]},{"n":3,"size":"Wide","desc":"Dan walks away with his arms behind his head, laughing. The laughter fills the empty street.","lines":[{"k":"say","who":"Dan","mod":"","t":"\"Go cry about it, freak!\""}],"rect":[3.0,20.94,94.0,19.98]},{"n":4,"size":"Large","desc":"Jared alone on the ground. He picks up the broken bracelet. A small scrape on his cheek, a fresh bruise on his forearm. His hands shake, but he says nothing and does not look around for help.","lines":[{"k":"sfx","who":"","mod":"","t":"\"SHAKE SHAKE\""}],"rect":[3.0,42.52,94.0,54.48]}]},{"n":14,"title":"The walk home","splash":false,"layout":"wide panel, two small panels, a medium panel, a large panel at the bottom.","note":"do not show any violence at home, ever, on these pages. Fear, sound and shadow only.","panels":[{"n":1,"size":"Wide","desc":"Jared walks home along a quiet road at dusk, earbuds in, bag over his shoulder, his long shadow stretched behind him. The road is lined with old trees.","lines":[],"rect":[3.0,3.0,94.0,19.62]},{"n":2,"size":"Small","desc":"Jared touches the scrape on his cheek and looks at his fingers.","lines":[{"k":"say","who":"Jared","mod":"thinking","t":"\"It doesn't even hurt.\""}],"rect":[3.0,24.22,45.8,17.84]},{"n":3,"size":"Small","desc":"Jared slows down. His steps get heavier, and he stares at the road.","lines":[{"k":"say","who":"Jared","mod":"thinking","t":"\"Not like what's waiting at home.\""}],"rect":[51.2,24.22,45.8,17.84]},{"n":4,"size":"Medium","desc":"A memory panel, drawn in washed gray tones: a dark kitchen, a table crowded with empty bottles, a man's shadow on the wall, and a woman's trembling hands gripping the edge of a sink. Nothing violent is shown, only fear.","lines":[{"k":"cap","who":"","mod":"","t":"\"At home there is a father who drinks, and a mother who is afraid.\""},{"k":"say","who":"Dad","mod":"from the memory, muffled","t":"\"WHERE'S MY DINNER?!\""}],"rect":[3.0,43.66,94.0,17.84]},{"n":5,"size":"Large","desc":"Jared stops, picks up a stone, and throws it as hard as he can toward a huge old balete tree at the side of the road, with a long, silent, angry shout.","lines":[{"k":"say","who":"Jared","mod":"","t":"\"AAAAARGH!\""},{"k":"sfx","who":"","mod":"","t":"\"FWOOSH\""}],"rect":[3.0,63.1,94.0,33.9]}]},{"n":15,"title":"The Agta","splash":false,"layout":"wide panel, two small panels, a large panel at the bottom.","note":"DRAFT. The Agta is a mean spirited demon like spirit that preys on hatred and amplifies it. The design is a to do (see the todo list). Keep it a dark shape with red eyes for now.","panels":[{"n":1,"size":"Wide","desc":"The stone hits the trunk of the old balete tree.","lines":[{"k":"sfx","who":"","mod":"","t":"\"TOK!\""}],"rect":[3.0,3.0,94.0,18.16]},{"n":2,"size":"Small","desc":"Jared, already walking away, staring at his empty hand. He does not feel better.","lines":[{"k":"say","who":"Jared","mod":"","t":"\"...That didn't help.\""}],"rect":[3.0,22.76,45.8,12.71]},{"n":3,"size":"Small","desc":"Behind him, the tree is still. Then the dark between the roots seems to breathe. A leaf falls. The wind stops. The air turns cold.","lines":[{"k":"sfx","who":"","mod":"","t":"\"...DOKI\""}],"rect":[51.2,22.76,45.8,12.71]},{"n":4,"size":"Large","desc":"High in the branches, two red eyes open. A long, thin, shadowy figure curls around the branch, a crooked grin full of teeth. It looks down at Jared's back as he walks away.","lines":[{"k":"cap","who":"","mod":"","t":"\"The Agta. A hundred years of sleep, and a very bad mood.\""},{"k":"say","who":"Agta","mod":"","t":"\"Oh... what a delicious little hate.\""}],"rect":[3.0,37.07,94.0,59.93]}]},{"n":16,"title":"Jeff comes home","splash":false,"layout":"wide panel, two small panels, two medium panels at the bottom.","note":"","panels":[{"n":1,"size":"Wide","desc":"A small house at evening, windows glowing. A jeepney is parked outside with its hood open. A painted slogan on the side reads GOD IS GOOD.","lines":[{"k":"cap","who":"","mod":"","t":"\"Meanwhile.\""}],"rect":[3.0,3.0,94.0,21.79]},{"n":2,"size":"Small","desc":"Jeff opens the door and steps in, bag on his shoulder.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"I'm home.\""}],"rect":[3.0,26.39,45.8,16.34]},{"n":3,"size":"Small","desc":"Inside the house: a small door bursts open, and two blurred shapes charge down the hall.","lines":[{"k":"sfx","who":"","mod":"","t":"\"PAT PAT PAT PAT\""}],"rect":[51.2,26.39,45.8,16.34]},{"n":4,"size":"Medium","desc":"Two five year old twin girls leap at Jeff and grab one leg each.","lines":[{"k":"cap","who":"","mod":"","t":"\"Gail and Janelle. Five years old. Professional huggers.\""},{"k":"say","who":"Gail","mod":"","t":"\"KUYA!\""},{"k":"say","who":"Janelle","mod":"","t":"\"KUYA'S HOME!\""}],"rect":[3.0,44.34,45.8,52.66]},{"n":5,"size":"Medium","desc":"Jeff with a twin on each leg like a pair of koalas, a flat annoyed stare, ears turning slightly red.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"Get off. I just got home.\""},{"k":"say","who":"Gail","mod":"","t":"\"No.\""},{"k":"say","who":"Janelle","mod":"","t":"\"Never.\""}],"rect":[51.2,44.34,45.8,52.66]}]},{"n":17,"title":"Two koalas","splash":false,"layout":"two small panels, a medium panel and a small panel, a large panel at the bottom.","note":"","panels":[{"n":1,"size":"Small","desc":"Jeff drags himself down the hall, a twin clinging to each leg. Deadpan.","lines":[{"k":"sfx","who":"","mod":"","t":"\"DRAG DRAG\""}],"rect":[3.0,3.0,45.8,18.16]},{"n":2,"size":"Small","desc":"Janelle holds up a drawing of a purple haired stick figure.","lines":[{"k":"say","who":"Janelle","mod":"","t":"\"I drew you, Kuya!\""}],"rect":[51.2,3.0,45.8,18.16]},{"n":3,"size":"Medium","desc":"Jeff looks at the drawing. The stick figure has a huge head and a tiny body, and a banana hat.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"Why do I have a banana on my head?\""},{"k":"say","who":"Janelle","mod":"","t":"\"Because you're handsome.\""},{"k":"say","who":"Jeff","mod":"","t":"\"...That doesn't make sense.\""}],"rect":[3.0,22.76,54.96,27.24]},{"n":4,"size":"Small","desc":"Gail sticks a heart sticker on Jeff's cheek while he's distracted.","lines":[],"rect":[60.36,22.76,36.64,27.24]},{"n":5,"size":"Large","desc":"Jeff tries to look annoyed, with a sticker on his cheek and a twin on each leg. His mouth fights a tiny smile and loses. Mama's voice calls from the kitchen.","lines":[{"k":"say","who":"Mama","mod":"from the kitchen","t":"\"Girls! Let your Kuya breathe!\""},{"k":"say","who":"Gail And Janelle","mod":"","t":"\"NO!\""}],"rect":[3.0,51.6,94.0,45.4]}]},{"n":18,"title":"Dinner with Mama","splash":false,"layout":"wide panel, two small panels, two medium panels at the bottom.","note":"","panels":[{"n":1,"size":"Wide","desc":"The family kitchen. A table with steaming rice and tinola. Mama, with an apron and a ladle in her hand, is at the stove.","lines":[{"k":"cap","who":"","mod":"","t":"\"Mama. Runs the house like a general, with soup.\""}],"rect":[3.0,3.0,94.0,21.79]},{"n":2,"size":"Small","desc":"Jeff sits and starts eating. The twins sit on either side of him.","lines":[{"k":"sfx","who":"","mod":"","t":"\"NOM NOM\""}],"rect":[3.0,26.39,45.8,23.61]},{"n":3,"size":"Small","desc":"Mama sets down a bowl and studies him closely.","lines":[{"k":"say","who":"Mama","mod":"","t":"\"So? How was school?\""}],"rect":[51.2,26.39,45.8,23.61]},{"n":4,"size":"Medium","desc":"Jeff, mouth full.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"Good. Nobody died.\""},{"k":"say","who":"Mama","mod":"","t":"\"That's your standard now?\""},{"k":"say","who":"Jeff","mod":"","t":"\"It's a high standard, Ma.\""}],"rect":[3.0,51.6,45.8,45.4]},{"n":5,"size":"Medium","desc":"Mama, with the ladle in one hand, narrows her eyes.","lines":[{"k":"say","who":"Mama","mod":"","t":"\"And Hal? Is he still eating enough? That poor little boy.\""},{"k":"say","who":"Jeff","mod":"","t":"\"Ma, he's not little. He's compact.\""}],"rect":[51.2,51.6,45.8,45.4]}]},{"n":19,"title":"Mama and the twins","splash":false,"layout":"two small panels, three wide panels stacked below.","note":"","panels":[{"n":1,"size":"Small","desc":"Mama slides a piece of fish onto Jeff's plate.","lines":[{"k":"say","who":"Mama","mod":"","t":"\"Eat more. You're too thin.\""}],"rect":[3.0,3.0,45.8,19.62]},{"n":2,"size":"Small","desc":"Janelle's little hand sneaks across the table and steals the fish from Jeff's plate.","lines":[{"k":"sfx","who":"","mod":"","t":"\"SNATCH\""}],"rect":[51.2,3.0,45.8,19.62]},{"n":3,"size":"Wide","desc":"Jeff, without even looking, takes the fish back from her fork. Janelle gasps. Gail gives her a thumbs up.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"Nice try.\""},{"k":"say","who":"Janelle","mod":"","t":"\"...How?\""},{"k":"say","who":"Jeff","mod":"","t":"\"I have eyes in the back of my head.\""}],"rect":[3.0,24.22,94.0,23.19]},{"n":4,"size":"Wide","desc":"Mama, leaning on the table with her chin in her hand and a sly smile.","lines":[{"k":"say","who":"Mama","mod":"","t":"\"And any girlfriend I should know about?\""}],"rect":[3.0,49.02,94.0,23.19]},{"n":5,"size":"Wide","desc":"Jeff chokes on his rice. The twins burst into giggles.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"Ma! Eat your own rice!\""},{"k":"say","who":"Gail","mod":"","t":"\"Kuya has a girlfriend!\""},{"k":"say","who":"Janelle","mod":"","t":"\"Kuya has a banana girlfriend!\""},{"k":"sfx","who":"","mod":"","t":"\"COUGH COUGH\""}],"rect":[3.0,73.81,94.0,23.19]}]},{"n":20,"title":"Papa","splash":false,"layout":"wide panel, two small panels, a large panel and a medium panel at the bottom.","note":"Hint only, not explained yet. Papa's old carved charm is a Babaylan symbol. The reveal that he was a Babaylan comes later. TO CONFIRM when.","panels":[{"n":1,"size":"Wide","desc":"The door at the back of the kitchen swings open. A tall man stands in the doorway, backlit by the yard light, a grease stained towel over his shoulder.","lines":[{"k":"sfx","who":"","mod":"","t":"\"CREAK\""}],"rect":[3.0,3.0,94.0,19.98]},{"n":2,"size":"Small","desc":"The man's face: tired eyes, a faint smile, grease smudged on his cheek. A small carved wooden charm hangs from a cord around his neck.","lines":[{"k":"cap","who":"","mod":"","t":"\"Papa. Jeepney driver. Grease is his cologne.\""}],"rect":[3.0,24.58,45.8,16.34]},{"n":3,"size":"Small","desc":"Papa, with a nod toward the yard.","lines":[{"k":"say","who":"Papa","mod":"","t":"\"Jeff. The jeepney is coughing again. Come help me.\""}],"rect":[51.2,24.58,45.8,16.34]},{"n":4,"size":"Large","desc":"The yard. The jeepney sits with its hood open, a work lamp hanging over the engine. Jeff and Papa lean over the engine side by side, in the same posture, with the same frown.","lines":[{"k":"sfx","who":"","mod":"","t":"\"COUGH SPUTTER\""}],"rect":[3.0,42.52,54.96,54.48]},{"n":5,"size":"Medium","desc":"Papa hands Jeff a wrench.","lines":[{"k":"say","who":"Papa","mod":"","t":"\"Hold this. No, the other one.\""},{"k":"say","who":"Jeff","mod":"","t":"\"Pa, they're the same wrench.\""},{"k":"say","who":"Papa","mod":"","t":"\"The other one.\""}],"rect":[60.36,42.52,36.64,54.48]}]},{"n":21,"title":"The jeepney talk","splash":false,"layout":"two small panels, a large panel, two small panels at the bottom.","note":"","panels":[{"n":1,"size":"Small","desc":"Papa, bent over the engine with a flashlight in his teeth, eyes on the engine.","lines":[{"k":"say","who":"Papa","mod":"","t":"\"Mama says your marks are high again.\""}],"rect":[3.0,3.0,45.8,21.79]},{"n":2,"size":"Small","desc":"Jeff, tightening a bolt.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"They're okay.\""}],"rect":[51.2,3.0,45.8,21.79]},{"n":3,"size":"Large","desc":"Papa takes the flashlight out of his mouth and looks at Jeff over the open hood, one eyebrow up, with the work lamp lighting his face from below.","lines":[{"k":"say","who":"Papa","mod":"","t":"\"High marks. Every time. You're not cheating, are you?\""},{"k":"say","who":"Jeff","mod":"","t":"\"Pa. I just study. A lot.\""}],"rect":[3.0,26.39,94.0,36.32]},{"n":4,"size":"Small","desc":"Jeff, eyes sparkling.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"That way, when I'm done, I'm free.\""}],"rect":[3.0,64.31,45.8,32.69]},{"n":5,"size":"Small","desc":"Papa, with a sly half smile.","lines":[{"k":"say","who":"Papa","mod":"","t":"\"Free for what?\""}],"rect":[51.2,64.31,45.8,32.69]}]},{"n":22,"title":"Arnis","splash":false,"layout":"wide panel, two small panels, a large panel at the bottom.","note":"optional beat, TO CONFIRM. Papa pauses for a second and looks out toward the dark street, as if he felt something. Then he shakes it off. A hint that Babaylan senses never fully retire.","panels":[{"n":1,"size":"Wide","desc":"The garage wall. Two worn rattan sticks hang on hooks above a tool bench. Jeff glances at them, then back at his father.","lines":[{"k":"say","who":"Jeff","mod":"","t":"\"Arnis. You promised to teach me the next form.\""}],"rect":[3.0,3.0,94.0,21.79]},{"n":2,"size":"Small","desc":"Papa chuckles and shakes his head.","lines":[{"k":"say","who":"Papa","mod":"","t":"\"A son who studies hard so he can get hit with sticks.\""}],"rect":[3.0,26.39,45.8,21.79]},{"n":3,"size":"Small","desc":"Papa, with a fond look.","lines":[{"k":"say","who":"Papa","mod":"","t":"\"Your mother is proud and worried at the same time.\""},{"k":"say","who":"Jeff","mod":"","t":"\"Mostly proud?\""}],"rect":[51.2,26.39,45.8,21.79]},{"n":4,"size":"Large","desc":"Papa reaches in and turns the key. The jeepney's engine roars to life, its headlights blazing. Father and son look at the machine, then at each other, with the same grin.","lines":[{"k":"say","who":"Papa","mod":"","t":"\"Finish the engine first. Then the sticks.\""},{"k":"sfx","who":"","mod":"","t":"\"VROOOOM\""}],"rect":[3.0,49.78,94.0,47.22]}]},{"n":23,"title":"Jared at home","splash":false,"layout":"wide panel, two small panels, two medium panels at the bottom.","note":"nothing violent is shown here either. Sound, shadow and Jared's face only.","panels":[{"n":1,"size":"Wide","desc":"Night. A small, narrow house with one dim upstairs window. Inside, Jared's room: band posters, a desk lamp, a notebook, a cracked mirror. The broken bracelet lies on the desk.","lines":[{"k":"cap","who":"","mod":"","t":"\"Jared's house.\""}],"rect":[3.0,3.0,94.0,19.98]},{"n":2,"size":"Small","desc":"Jared sits at the desk with headphones around his neck, opens the notebook, and tries to draw.","lines":[],"rect":[3.0,24.58,45.8,18.16]},{"n":3,"size":"Small","desc":"From downstairs, the muffled sound of a TV and a man's slurred shouting. We only see the floor and a thin line of light under the door.","lines":[{"k":"say","who":"Dad","mod":"muffled, from downstairs","t":"\"WHERE'S MY DINNER?!\""},{"k":"sfx","who":"","mod":"","t":"\"CRASH\""}],"rect":[51.2,24.58,45.8,18.16]},{"n":4,"size":"Medium","desc":"Jared puts the headphones on and presses them against his ears, eyes squeezed shut, the veins in his temples showing.","lines":[{"k":"sfx","who":"","mod":"","t":"\"THROB THROB\""}],"rect":[3.0,44.34,45.8,52.66]},{"n":5,"size":"Medium","desc":"Through the headphones, a small, frightened voice from downstairs. Jared's fist closes on the pencil and it snaps.","lines":[{"k":"say","who":"Mama","mod":"muffled, from downstairs","t":"\"Please... lower your voice...\""},{"k":"sfx","who":"","mod":"","t":"\"SNAP\""}],"rect":[51.2,44.34,45.8,52.66]}]},{"n":24,"title":"What Jared tells himself","splash":false,"layout":"large panel, two small panels, a wide panel at the bottom.","note":"","panels":[{"n":1,"size":"Large","desc":"Jared sits on the edge of his bed, staring at the broken bracelet in his palm. His reflection in the cracked mirror is split in two.","lines":[{"k":"say","who":"Jared","mod":"muttering","t":"\"I'm taller than him now. I could stop him.\""}],"rect":[3.0,3.0,94.0,45.4]},{"n":2,"size":"Small","desc":"Jared, looking away.","lines":[{"k":"say","who":"Jared","mod":"","t":"\"But every time, I just... stand there.\""}],"rect":[3.0,50.0,45.8,18.16]},{"n":3,"size":"Small","desc":"Jared, jaw tight.","lines":[{"k":"say","who":"Jared","mod":"","t":"\"I can't even stand up to Dan. How am I supposed to stand up to him?\""}],"rect":[51.2,50.0,45.8,18.16]},{"n":4,"size":"Wide","desc":"Jared clenches his fist on his knee. The lamp flickers. Behind him, the curtain stirs, though the window is closed.","lines":[{"k":"say","who":"Jared","mod":"","t":"\"I hate this. I hate him. I hate that I can't do anything.\""},{"k":"sfx","who":"","mod":"","t":"\"THROB\""}],"rect":[3.0,69.76,94.0,27.24]}]},{"n":25,"title":"The watcher","splash":false,"layout":"wide panel, two small panels, a large panel at the bottom.","note":"","panels":[{"n":1,"size":"Wide","desc":"Jared's house from outside at night, one window lit. A huge old tree stands beside it, its branches reaching toward the roof.","lines":[],"rect":[3.0,3.0,94.0,27.24]},{"n":2,"size":"Small","desc":"A branch bends. Two red eyes open in the leaves.","lines":[],"rect":[3.0,31.84,45.8,18.16]},{"n":3,"size":"Small","desc":"The Agta, crouched on the branch outside Jared's window, tilts its head and sniffs the air.","lines":[{"k":"sfx","who":"","mod":"","t":"\"SNIFF\""}],"rect":[51.2,31.84,45.8,18.16]},{"n":4,"size":"Large","desc":"Close up of the Agta's grin, with the lit window of Jared's room reflected in its red eyes. Through the glass, Jared is a tiny figure on the edge of his bed.","lines":[{"k":"say","who":"Agta","mod":"","t":"\"I can feel it from here. The anger. The shame. So much hate, for a boy who has so little.\""},{"k":"say","who":"Agta","mod":"softly","t":"\"Let me help you with that.\""}],"rect":[3.0,51.6,94.0,45.4]}]},{"n":26,"title":"Lights out","splash":false,"layout":"two small panels, a wide panel, a large panel at the bottom.","note":"","panels":[{"n":1,"size":"Small","desc":"Jared rubs his eyes and closes the notebook.","lines":[{"k":"say","who":"Jared","mod":"","t":"\"Just sleep. Tomorrow's the same anyway.\""}],"rect":[3.0,3.0,45.8,21.79]},{"n":2,"size":"Small","desc":"He takes off his spiked belt and bracelets and sets them on the desk one by one. Without them, he looks a lot younger.","lines":[],"rect":[51.2,3.0,45.8,21.79]},{"n":3,"size":"Wide","desc":"Jared crosses the room and stops by the door, next to the light switch. Downstairs, the shouting has stopped. The house is quiet.","lines":[],"rect":[3.0,26.39,94.0,18.16]},{"n":4,"size":"Large","desc":"Jared, standing by the switch with one hand raised. His shadow stretches long across the wall behind him. In the dark window, behind his reflection, two red eyes.","lines":[{"k":"say","who":"Jared","mod":"quietly, toward the floor","t":"\"Good night, Ma.\""}],"rect":[3.0,46.15,94.0,50.85]}]},{"n":27,"title":"The merge","splash":false,"layout":"wide panel, three small panels, a large panel at the bottom.","note":"DRAFT. This is the scary beat of the chapter, so use a lot of black.","panels":[{"n":1,"size":"Wide","desc":"Jared's hand flips the switch. The room goes black. Jared stands in the dark, not moving yet.","lines":[{"k":"sfx","who":"","mod":"","t":"\"CLICK\""}],"rect":[3.0,3.0,94.0,21.79]},{"n":2,"size":"Small","desc":"Moonlight through the window. The curtain waves.","lines":[],"rect":[3.0,26.39,29.73,18.16]},{"n":3,"size":"Small","desc":"The tree outside rattles. The branch where the Agta sat is empty.","lines":[],"rect":[35.13,26.39,29.73,18.16]},{"n":4,"size":"Small","desc":"A dark shape launches from the branch, arms wide.","lines":[{"k":"sfx","who":"","mod":"","t":"\"SWOOSH\""}],"rect":[67.27,26.39,29.73,18.16]},{"n":5,"size":"Large","desc":"The Agta flies through the window like smoke, the glass stays whole, and dives into the long shadow on the floor behind Jared. The shadow ripples. For one second, the shadow has red eyes. Jared, still standing in the dark, notices nothing.","lines":[{"k":"sfx","who":"","mod":"","t":"\"ZUUUUM\""}],"rect":[3.0,46.15,94.0,50.85]}]},{"n":28,"title":"Sleep","splash":false,"layout":"wide panel, two small panels, a wide panel, a large panel at the bottom.","note":"the light is the banaag, the first glimmer (the chapter title). The dream sequence starts here. DRAFT, the creator will add the details.","panels":[{"n":1,"size":"Wide","desc":"Jared's shadow on the floor, in the moonlight. It is a little too long and a little too dark, and its shape does not quite match Jared's.","lines":[],"rect":[3.0,3.0,94.0,17.84]},{"n":2,"size":"Small","desc":"Jared lies down on the bed, tired.","lines":[{"k":"say","who":"Jared","mod":"","t":"\"Why am I so tired all of a sudden...\""}],"rect":[3.0,22.44,45.8,17.84]},{"n":3,"size":"Small","desc":"He pulls the blanket up to his chin.","lines":[],"rect":[51.2,22.44,45.8,17.84]},{"n":4,"size":"Wide","desc":"His eyes close. His breathing slows.","lines":[{"k":"sfx","who":"","mod":"","t":"\"ZZZ\""}],"rect":[3.0,41.88,94.0,17.84]},{"n":5,"size":"Large","desc":"A pure black panel. Far in the center, one tiny faint light, a glimmer of dawn, grows slowly brighter.","lines":[{"k":"cap","who":"","mod":"","t":"\"And so Jared dreamed.\""}],"rect":[3.0,61.32,94.0,35.68]}]},{"n":29,"title":"Dream sequence, to be added","splash":false,"layout":"a single panel.","note":"","panels":[{"n":1,"size":"Large","desc":"TO BE ADDED by the creator. Dream sequence.","lines":[],"rect":[3.0,3.0,94.0,94.0]}]},{"n":30,"title":"To be added","splash":false,"layout":"a single panel.","note":"","panels":[{"n":1,"size":"Large","desc":"TO BE ADDED by the creator.","lines":[],"rect":[3.0,3.0,94.0,94.0]}]},{"n":31,"title":"To be added","splash":false,"layout":"a single panel.","note":"","panels":[{"n":1,"size":"Large","desc":"TO BE ADDED by the creator.","lines":[],"rect":[3.0,3.0,94.0,94.0]}]},{"n":32,"title":"To be added","splash":false,"layout":"a single panel.","note":"","panels":[{"n":1,"size":"Large","desc":"TO BE ADDED by the creator.","lines":[],"rect":[3.0,3.0,94.0,94.0]}]},{"n":33,"title":"To be added","splash":false,"layout":"a single panel.","note":"","panels":[{"n":1,"size":"Large","desc":"TO BE ADDED by the creator.","lines":[],"rect":[3.0,3.0,94.0,94.0]}]},{"n":34,"title":"To be added","splash":false,"layout":"a single panel.","note":"","panels":[{"n":1,"size":"Large","desc":"TO BE ADDED by the creator.","lines":[],"rect":[3.0,3.0,94.0,94.0]}]},{"n":35,"title":"To be added","splash":false,"layout":"a single panel.","note":"","panels":[{"n":1,"size":"Large","desc":"TO BE ADDED by the creator.","lines":[],"rect":[3.0,3.0,94.0,94.0]}]},{"n":36,"title":"To be added","splash":false,"layout":"a single panel.","note":"","panels":[{"n":1,"size":"Large","desc":"TO BE ADDED by the creator.","lines":[],"rect":[3.0,3.0,94.0,94.0]}]},{"n":37,"title":"To be added","splash":false,"layout":"a single panel.","note":"","panels":[{"n":1,"size":"Large","desc":"TO BE ADDED by the creator.","lines":[],"rect":[3.0,3.0,94.0,94.0]}]},{"n":38,"title":"To be added","splash":false,"layout":"a single panel.","note":"","panels":[{"n":1,"size":"Large","desc":"TO BE ADDED by the creator.","lines":[],"rect":[3.0,3.0,94.0,94.0]}]},{"n":39,"title":"To be added","splash":false,"layout":"a single panel.","note":"","panels":[{"n":1,"size":"Large","desc":"TO BE ADDED by the creator.","lines":[],"rect":[3.0,3.0,94.0,94.0]}]},{"n":40,"title":"To be added","splash":false,"layout":"a single panel.","note":"","panels":[{"n":1,"size":"Large","desc":"TO BE ADDED by the creator.","lines":[],"rect":[3.0,3.0,94.0,94.0]}]},{"n":41,"title":"To be added","splash":false,"layout":"a single panel.","note":"","panels":[{"n":1,"size":"Large","desc":"TO BE ADDED by the creator.","lines":[],"rect":[3.0,3.0,94.0,94.0]}]},{"n":42,"title":"To be added","splash":false,"layout":"a single panel.","note":"","panels":[{"n":1,"size":"Large","desc":"TO BE ADDED by the creator.","lines":[],"rect":[3.0,3.0,94.0,94.0]}]},{"n":43,"title":"To be added","splash":false,"layout":"a single panel.","note":"","panels":[{"n":1,"size":"Large","desc":"TO BE ADDED by the creator.","lines":[],"rect":[3.0,3.0,94.0,94.0]}]},{"n":44,"title":"To be added","splash":false,"layout":"a single panel.","note":"","panels":[{"n":1,"size":"Large","desc":"TO BE ADDED by the creator.","lines":[],"rect":[3.0,3.0,94.0,94.0]}]},{"n":45,"title":"To be added","splash":false,"layout":"a single panel.","note":"","panels":[{"n":1,"size":"Large","desc":"TO BE ADDED by the creator.","lines":[],"rect":[3.0,3.0,94.0,94.0]}]},{"n":46,"title":"To be added","splash":false,"layout":"a single panel.","note":"","panels":[{"n":1,"size":"Large","desc":"TO BE ADDED by the creator.","lines":[],"rect":[3.0,3.0,94.0,94.0]}]},{"n":47,"title":"To be added","splash":false,"layout":"a single panel.","note":"","panels":[{"n":1,"size":"Large","desc":"TO BE ADDED by the creator.","lines":[],"rect":[3.0,3.0,94.0,94.0]}]},{"n":48,"title":"To be added","splash":false,"layout":"a single panel.","note":"","panels":[{"n":1,"size":"Large","desc":"TO BE ADDED by the creator.","lines":[],"rect":[3.0,3.0,94.0,94.0]}]},{"n":49,"title":"To be added","splash":false,"layout":"a single panel.","note":"","panels":[{"n":1,"size":"Large","desc":"TO BE ADDED by the creator.","lines":[],"rect":[3.0,3.0,94.0,94.0]}]},{"n":50,"title":"To be added","splash":false,"layout":"a single panel.","note":"","panels":[{"n":1,"size":"Large","desc":"TO BE ADDED by the creator.","lines":[],"rect":[3.0,3.0,94.0,94.0]}]}];
